d colspan='4' class='c'>${esc(data.communication)}</td></tr><tr><td class='sh' colspan='4'>${Lb.otherNotes}</td></tr><tr><td colspan='4' class='c'>${esc(data.otherNotes)}</td></tr><tr><td colspan='2'><b>${Lb.samplingTests}</b></td><td colspan='2'><b>${Lb.qualityInspection}</b></td></tr><tr><td colspan='2' class='c'>${esc(data.samplingTests)}</td><td colspan='2' class='c'>${esc(data.qualityInspection)}</td></tr><tr><td><b>${Lb.supervisor}</b></td><td></td><td><b>${Lb.inspector}</b></td><td>${esc(data.supervisor)}</td></tr></table>${photoHtml}</body></html>`;
}
const pad2 = n => String(n).padStart(2, '0');
const now2 = new Date();
const genStamp = `${now2.getFullYear()}-${pad2(now2.getMonth() + 1)}-${pad2(now2.getDate())} ${pad2(now2.getHours())}:${pad2(now2.getMinutes())}`;
const html = buildHtml(L, d, genStamp);
let htmlZH = buildHtml(LZH, dZH, genStamp);
if (geminiStatus !== 'success') {
  const warnBanner = "<div style='background:#fee2e2;border:2px solid #e53e3e;color:#991b1b;padding:8px 12px;margin-bottom:8px;font-weight:bold;font-size:11pt'>⚠️ 自動翻譯失敗，以下內容為原文（非正式中文翻譯），請人工確認 / Translation failed — content below is original language</div>";
  htmlZH = htmlZH.replace('<body>', '<body>' + warnBanner);
}
const variants = [
  { lang: 'contractor', html: html, fileName: d.fileName },
