const items = $input.all();
const prevItems = $('Wait Job').all();
return items.map((it, i) => {
  const prevAttempts = (prevItems[i] && prevItems[i].json.attempts) || 0;
  return { json: { ...it.json, attempts: prevAttempts + 1 } };
});

const items = $input.all();
const isTerminal = j => ['success','failed','aborted'].includes(j.status) || j.attempts >= 20;
const allDone = items.every(it => isTerminal(it.json));
return items.map(it => ({ json: { ...it.json, allDone } }));
